from typing import Sequence

def distance(x: Sequence[int], y: Sequence[int]) -> int:
    if len(x) != len(y): raise ValueError("unequal lengths")
    return sum(a != b for a, b in zip(x, y))

def add(x: Sequence[int], y: Sequence[int]) -> tuple[int, ...]:
    if len(x) != len(y): raise ValueError("unequal lengths")
    return tuple(a ^ b for a, b in zip(x, y))

codeword = (1, 0, 1, 1, 0, 0, 1, 0)
error    = (0, 1, 0, 0, 0, 1, 0, 0)
ciphertext = add(codeword, error)
weight = sum(error)
assert distance(ciphertext, codeword) == weight
print({"codeword": codeword, "error": error, "ciphertext": ciphertext,
       "error_weight": weight, "distance": distance(ciphertext, codeword)})

