from typing import Sequence

def verify_bounded_distance(candidate: Sequence[int], ciphertext: Sequence[int], radius: int) -> bool:
    """Accept exactly when the candidate lies in the ciphertext's Hamming ball."""
    if radius < 0 or len(candidate) != len(ciphertext):
        return False
    return sum(a != b for a, b in zip(candidate, ciphertext)) <= radius

def compose_game_hops(epsilon_key: float, epsilon_decode: float) -> float:
    """Compose two nonnegative transition bounds by the triangle inequality."""
    if epsilon_key < 0 or epsilon_decode < 0:
        raise ValueError("bounds must be nonnegative")
    return epsilon_key + epsilon_decode

def choose_multiplicative(n: int, t: int) -> int:
    """Compute C(n,t) using exact divisions and O(min(t,n-t)) iterations."""
    if not 0 <= t <= n:
        raise ValueError("require 0 <= t <= n")
    t = min(t, n - t)
    value = 1
    for k in range(1, t + 1):
        value = value * (n - k + 1) // k
    return value

